import { GoogleGenAI } from "@google/genai";

// Extension for window object to support AI Studio key selection
declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

export const generateAlbumVideo = async (
  prompt: string,
  onProgress: (msg: string) => void
): Promise<string> => {
  // 1. Handle API Key Selection (Mandatory for Veo)
  const hasKey = await window.aistudio.hasSelectedApiKey();
  if (!hasKey) {
    onProgress("Seleccionando clave de API para la generación de vídeo...");
    await window.aistudio.openSelectKey();
    // Proceed assuming success as per guidelines race condition rule
  }

  // 2. Initialize AI (Must use a new instance to ensure latest key)
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  try {
    onProgress("Iniciando la creación cinematográfica de tus recuerdos...");

    let operation = await ai.models.generateVideos({
      model: 'veo-3.1-fast-generate-preview',
      prompt: `A high-quality cinematic travel montage featuring these locations: ${prompt}. Dynamic transitions, vibrant colors, professional travel vlog style.`,
      config: {
        numberOfVideos: 1,
        resolution: '1080p',
        aspectRatio: '16:9'
      }
    });

    const loadingMessages = [
      "Renderizando paisajes...",
      "Añadiendo toques cinematográficos...",
      "Compilando tus destinos favoritos...",
      "Casi listo, puliendo detalles finales...",
      "Ajustando la iluminación de tus recuerdos..."
    ];
    let msgIndex = 0;

    while (!operation.done) {
      onProgress(loadingMessages[msgIndex % loadingMessages.length]);
      msgIndex++;
      await new Promise(resolve => setTimeout(resolve, 10000));

      try {
        operation = await ai.operations.getVideosOperation({ operation: operation });
      } catch (pollError: any) {
        if (pollError.message?.includes("Requested entity was not found")) {
          // Reset key selection if entity not found error occurs
          await window.aistudio.openSelectKey();
          throw new Error("Error de autorización. Por favor, selecciona una clave válida de un proyecto con facturación activa.");
        }
        throw pollError;
      }
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) throw new Error("No se pudo obtener el enlace del vídeo.");

    onProgress("Descargando vídeo final...");
    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);

  } catch (error: any) {
    console.error("Video generation error:", error);
    throw new Error(error.message || "Falló la generación del vídeo.");
  }
};

