  const hasKey = await window.aistudio.hasSelectedApiKey();
  if (!hasKey) {
    onProgress("Configurando acceso seguro a Veo 3.1...");
    await window.aistudio.openSelectKey();
  }

  // 2. Inicializar AI (Instancia nueva para asegurar la clave más reciente)
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  try {
    onProgress("Preparando activos visuales de tus destinos...");

    // Preparar imágenes de referencia (hasta 3 de diferentes lugares)
    const referenceImagesPayload = groups.slice(0, 3).map(group => ({
      image: {
        imageBytes: group.images[0].split(',')[1], // Extraer base64 puro
        mimeType: 'image/jpeg',
      },
      referenceType: VideoGenerationReferenceType.ASSET,
    }));

    const prompt = `A cinematic travel montage with smooth transitions featuring: ${groups.map(g => g.locationName).join(", ")}. High quality, 4k travel vlog style, professional color grading.`;

    onProgress("Iniciando renderizado en la nube...");

    let operation = await ai.models.generateVideos({
      model: 'veo-3.1-generate-preview',
      prompt: prompt,
      config: {
        numberOfVideos: 1,
        referenceImages: referenceImagesPayload,
        resolution: '720p', // Requerido para múltiples imágenes de referencia
        aspectRatio: '16:9'
      }
    });

    const loadingMessages = [
      "Analizando tus capturas...",
      "Generando transiciones fluidas...",
      "Aplicando corrección de color...",
      "Renderizando paisajes cinemáticos...",
      "Casi listo, puliendo detalles finales..."
    ];
    let msgIndex = 0;

    while (!operation.done) {
      onProgress(loadingMessages[msgIndex % loadingMessages.length]);
      msgIndex++;
      await new Promise(resolve => setTimeout(resolve, 10000));

      try {
        operation = await ai.operations.getVideosOperation({ operation: operation });
      } catch (pollError: any) {
        if (pollError.message?.includes("Requested entity was not found")) {
          await window.aistudio.openSelectKey();
          throw new Error("Error de autorización. Por favor, selecciona una clave de un proyecto con facturación activa.");
        }
        throw pollError;
      }
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) throw new Error("No se pudo obtener el video generado.");

    onProgress("Finalizando descarga...");
    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);

  } catch (error: any) {
    console.error("Error en generación de video:", error);
    throw new Error(error.message || "Fallo en la creación del video cinematográfico.");
  }
};

