  try {
    // For multimodal reasoning and image analysis with search grounding, gemini-3-pro-preview is recommended.
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: base64Image.split(',')[1] || base64Image } },
          { text: prompt }
        ]
      },
      config: {
        // Enforce JSON output while using search grounding tools.
        responseMimeType: "application/json",
        tools: [{ googleSearch: {} }]
      }
    });

    // Directly access the .text property of GenerateContentResponse.
    const resultText = response.text || "{}";
    const data = JSON.parse(resultText);

    // Extract grounding chunks to get search references and URLs.
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks as GroundingChunk[] | undefined;
    const links = chunks?.filter(c => c.web?.uri).map(c => c.web!.uri) || [];

    return {
      ...data,
      googleMapsLinks: links
    };
  } catch (error) {
    console.error("Error analyzing image:", error);
    throw new Error("No se pudo analizar la imagen. Inténtalo de nuevo.");
  }
};

