import { GoogleGenAI, VideoGenerationReferenceType } from "@google/genai";
import { AlbumLocationGroup } from "../types";

export const generateAlbumVideo = async (
  groups: AlbumLocationGroup[],
  onProgress: (msg: string) => void
): Promise<string> => {
  // 1. Manejar la selección de API Key (Obligatorio para Veo)
  const aistudio = (window as any).aistudio;
  const hasKey = await aistudio.hasSelectedApiKey();
  if (!hasKey) {
    onProgress("Configurando acceso seguro a Veo 3.1...");
    await aistudio.openSelectKey();
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    onProgress("Preparando tus fotos originales...");

    // Seleccionamos hasta 3 imágenes representativas como ASSETS de referencia
    const referenceImagesPayload = groups.slice(0, 3).map(group => ({
      image: {
        imageBytes: group.images[0].split(',')[1], 
        mimeType: 'image/jpeg',
      },
      referenceType: VideoGenerationReferenceType.ASSET,
    }));

    // Construimos una lista de países para la música
    const locations = groups.map(g => g.locationName).join(", ");
    const countries = Array.from(new Set(groups.map(g => g.country).filter(Boolean))).join(", ");

    /**
     * PROMPT OPTIMIZADO:
     * - "Photo slideshow presentation": Define la estructura.
     * - "Faithfully use original visual content": Pide no alterar las fotos.
     * - "Professional transitions": Estilo PowerPoint.
     * - "Background music... authentic to": Personalización sonora.
     */
    const prompt = `
      Create a professional photo slideshow video presentation. 
      The video must faithfully use the visual content from the provided reference images as static slides without generative alterations or hallucinations.
      Style: Clean, elegant presentation similar to a high-end travel PowerPoint or Keynote.
      Transitions: Smooth professional cross-fades and subtle pans.
      Locations featured: ${locations}.
      Audio/Music: The background score must be high-quality instrumental music authentic to the cultures of ${countries}. 
      Ensure the soundtrack reflects the traditional melodies and atmosphere of these specific regions.
    `;

    onProgress("Componiendo la música y las transiciones...");

    let operation = await ai.models.generateVideos({
      model: 'veo-3.1-generate-preview',
      prompt: prompt,
      config: {
        numberOfVideos: 1,
        referenceImages: referenceImagesPayload,
        resolution: '720p',
        aspectRatio: '16:9'
      }
    });

    const loadingMessages = [
      "Sincronizando música cultural...",
      "Organizando diapositivas visuales...",
      "Aplicando transiciones elegantes...",
      "Renderizando presentación final...",
      "Casi listo, afinando el audio..."
    ];
    let msgIndex = 0;

    while (!operation.done) {
      onProgress(loadingMessages[msgIndex % loadingMessages.length]);
      msgIndex++;
      await new Promise(resolve => setTimeout(resolve, 10000));

      try {
        operation = await ai.operations.getVideosOperation({ operation: operation });
      } catch (pollError: any) {
        if (pollError.message?.includes("Requested entity was not found")) {
          await aistudio.openSelectKey();
          throw new Error("Error de autorización. Selecciona una clave con facturación activa.");
        }
        throw pollError;
      }
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) throw new Error("No se pudo obtener el video generado.");

    onProgress("Finalizando tu presentación...");
    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);

  } catch (error: any) {
    console.error("Error en generación de video:", error);
    throw new Error(error.message || "Fallo en la creación del video cinematográfico.");
  }
};

