  onProgress: (msg: string) => void
): Promise<string> => {
  const aistudio = (window as any).aistudio;
  const hasKey = await aistudio.hasSelectedApiKey();

  if (!hasKey) {
    onProgress("Configurando acceso para generación de video...");
    await aistudio.openSelectKey();
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    onProgress("Preparando tus fotos originales...");

    // Usamos hasta 3 imágenes como assets de referencia para guiar el modelo
    const referenceImagesPayload = groups.slice(0, 3).map(group => ({
      image: {
        imageBytes: group.images[0].split(',')[1],
        mimeType: 'image/jpeg',
      },
      referenceType: VideoGenerationReferenceType.ASSET,
    }));

    const countries = Array.from(new Set(groups.map(g => g.country).filter(Boolean))).join(", ");

    const prompt = `
      Create a high-quality professional photo slideshow. 
      STRICT REQUIREMENT: Use the original provided images EXACTLY as they are. 
      NO morphing, NO generative alterations, NO pixel re-interpretation. 
      The photos must remain static, exactly like a PowerPoint presentation.
      Transitions: Simple, elegant cross-fades between slides. 
      Music: Atmospheric instrumental background music featuring traditional instruments and scales from ${countries}. 
      The soundtrack must perfectly match the cultural identity of the locations shown.
    `;

    onProgress("Componiendo la música y el diaporama...");

    let operation = await ai.models.generateVideos({
      model: 'veo-3.1-generate-preview',
      prompt: prompt,
      config: {
        numberOfVideos: 1,
        resolution: '720p',
        aspectRatio: '16:9'
      }
    });

    const messages = [
      "Ajustando banda sonora cultural...",
      "Organizando diapositivas estáticas...",
      "Sincronizando transiciones limpias...",
      "Renderizando video en 720p...",
      "Finalizando presentación..."
    ];
    let msgIdx = 0;

    while (!operation.done) {
      onProgress(messages[msgIdx % messages.length]);
      msgIdx++;
      await new Promise(resolve => setTimeout(resolve, 10000));
      operation = await ai.operations.getVideosOperation({ operation: operation });
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) throw new Error("No se pudo obtener el video generado.");

    onProgress("Descargando presentación final...");
    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const blob = await response.blob();
    return URL.createObjectURL(blob);

  } catch (error: any) {
    console.error("Video Error:", error);
    throw new Error(error.message || "No se pudo crear la presentación.");
  }
};

