import { GoogleGenAI, Modality } from "@google/genai";

export const generateNarration = async (text: string): Promise<AudioBuffer> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Actúa como un guía turístico entusiasta. Narra lo siguiente de forma natural: ${text}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' }, // Voz cálida y profesional
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("No se pudo generar la narración de audio.");

  const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  const audioBuffer = await decodeAudioData(decode(base64Audio), audioContext, 24000, 1);

  return audioBuffer;
};

// Utilidades de decodificación de audio raw PCM
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const playAudioBuffer = (buffer: AudioBuffer) => {
  const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
  const source = ctx.createBufferSource();
  source.buffer = buffer;
  source.connect(ctx.destination);
  source.start();
  return source;
};

import React, { useState, useEffect, useRef } from 'react';
import { AlbumLocationGroup } from '../types';
import { generateNarration, playAudioBuffer } from '../services/audioService';

interface PresentationModeProps {
  group: AlbumLocationGroup;
  onClose: () => void;
}

const PresentationMode: React.FC<PresentationModeProps> = ({ group, onClose }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);
  const [isNarrating, setIsNarrating] = useState(false);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    let timer: number;
    if (isPlaying) {
      timer = window.setInterval(() => {
        setCurrentIndex((prev) => (prev + 1) % group.images.length);
      }, 4000);
    }
    return () => clearInterval(timer);
  }, [isPlaying, group.images.length]);

  const handleToggleNarration = async () => {
    if (isNarrating) {
      audioSourceRef.current?.stop();
      setIsNarrating(false);
      return;
    }

    try {
      setIsNarrating(true);
      const buffer = await generateNarration(`${group.locationName}. ${group.description}. Sabías que: ${group.facts.join(". ")}`);
      audioSourceRef.current = playAudioBuffer(buffer);
      audioSourceRef.current.onended = () => setIsNarrating(false);
    } catch (err) {
      console.error(err);
      setIsNarrating(false);
    }
  };

  useEffect(() => {
    return () => audioSourceRef.current?.stop();
  }, []);

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center animate-in fade-in duration-500">
      {/* Header / Controles Superiores */}
      <div className="absolute top-0 left-0 w-full p-6 flex items-center justify-between z-10 bg-gradient-to-b from-black/60 to-transparent">
        <div className="flex flex-col">
          <h2 className="text-white text-2xl font-black tracking-tight">{group.locationName}</h2>
          <p className="text-slate-300 text-sm font-medium">{currentIndex + 1} de {group.images.length} fotos originales</p>
        </div>
        <button 
          onClick={onClose}
          className="w-12 h-12 bg-white/10 hover:bg-white/20 rounded-full flex items-center justify-center text-white transition-colors"
        >
          <i className="fa-solid fa-xmark text-xl"></i>
        </button>
      </div>

      {/* Visor de Imágenes (Sin Alteración) */}
      <div className="relative w-full h-full flex items-center justify-center p-4 md:p-12">
        {group.images.map((img, idx) => (
          <img
            key={idx}
            src={img}
            alt="Presentación"
            className={`absolute max-w-full max-h-[85vh] object-contain transition-opacity duration-1000 shadow-2xl rounded-sm ${
              idx === currentIndex ? 'opacity-100' : 'opacity-0'
            }`}
          />
        ))}
      </div>

      {/* Controles Inferiores */}
      <div className="absolute bottom-0 left-0 w-full p-8 flex flex-col items-center gap-6 bg-gradient-to-t from-black/80 to-transparent">
        <div className="max-w-2xl text-center">
           <p className="text-white/90 text-lg md:text-xl font-medium leading-relaxed italic animate-in slide-in-from-bottom-2">
             "{group.description}"
           </p>
        </div>

        <div className="flex items-center gap-6">
          <button 
            onClick={() => setCurrentIndex((prev) => (prev - 1 + group.images.length) % group.images.length)}
            className="w-10 h-10 text-white/50 hover:text-white transition-colors"
          >
            <i className="fa-solid fa-chevron-left text-2xl"></i>
          </button>

          <button 
            onClick={() => setIsPlaying(!isPlaying)}
            className="w-16 h-16 bg-white text-black rounded-full flex items-center justify-center shadow-xl hover:scale-105 active:scale-95 transition-all"
          >
            <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'} text-xl`}></i>
          </button>

          <button 
            onClick={() => setCurrentIndex((prev) => (prev + 1) % group.images.length)}
            className="w-10 h-10 text-white/50 hover:text-white transition-colors"
          >
            <i className="fa-solid fa-chevron-right text-2xl"></i>
          </button>

          <div className="h-8 w-px bg-white/20 mx-2"></div>

          <button 
            onClick={handleToggleNarration}
            className={`flex items-center gap-2 px-6 py-3 rounded-full font-bold transition-all ${
              isNarrating ? 'bg-indigo-600 text-white animate-pulse' : 'bg-white/10 text-white hover:bg-white/20'
            }`}
          >
            <i className={`fa-solid ${isNarrating ? 'fa-volume-high' : 'fa-ear-listen'}`}></i>
            {isNarrating ? 'Escuchando Guía...' : 'Guía de Voz (IA)'}
          </button>
        </div>
      </div>
    </div>
  );
};

