// Este archivo ha sido reemplazado por audioService.ts y el componente PresentationMode
// para garantizar que las fotos originales no sufran alteraciones generativas.
export const deprecated = true;

import React, { useState, useEffect, useRef } from 'react';
import { generateNarration, playAudioBuffer } from '../services/audioService';

export interface Slide {
  image: string;
  locationName: string;
  description: string;
  facts: string[];
}

interface PresentationModeProps {
  slides: Slide[];
  onClose: () => void;
  title: string;
}

const PresentationMode: React.FC<PresentationModeProps> = ({ slides, onClose, title }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);
  const [progress, setProgress] = useState(0);
  const [isNarrating, setIsNarrating] = useState(false);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const SLIDE_DURATION = 5000; // 5 segundos por foto
  const currentSlide = slides[currentIndex];

  // Lógica de transición automática y barra de progreso
  useEffect(() => {
    let interval: number;
    let progressInterval: number;

    if (isPlaying) {
      const startTime = Date.now();

      interval = window.setInterval(() => {
        setCurrentIndex((prev) => (prev + 1) % slides.length);
        setProgress(0);
      }, SLIDE_DURATION);

      progressInterval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        const newProgress = Math.min((elapsed / SLIDE_DURATION) * 100, 100);
        setProgress(newProgress);
      }, 50);
    }

    return () => {
      clearInterval(interval);
      clearInterval(progressInterval);
    };
  }, [isPlaying, currentIndex, slides.length]);

  const handleToggleNarration = async () => {
    if (isNarrating) {
      audioSourceRef.current?.stop();
      setIsNarrating(false);
      return;
    }

    try {
      setIsPlaying(false); // Pausamos el auto-play mientras narra
      setIsNarrating(true);
      const text = `${currentSlide.locationName}. ${currentSlide.description}.`;
      const buffer = await generateNarration(text);
      audioSourceRef.current = playAudioBuffer(buffer);
      audioSourceRef.current.onended = () => {
        setIsNarrating(false);
        setIsPlaying(true);
      };
    } catch (err) {
      console.error(err);
      setIsNarrating(false);
      setIsPlaying(true);
    }
  };

  useEffect(() => {
    return () => audioSourceRef.current?.stop();
  }, []);

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center animate-in fade-in duration-500 overflow-hidden">
      {/* Barras de progreso superiores */}
      <div className="absolute top-0 left-0 w-full p-4 flex gap-1 z-20">
        {slides.map((_, idx) => (
          <div key={idx} className="h-1 flex-1 bg-white/20 rounded-full overflow-hidden">
            <div 
              className="h-full bg-white transition-all duration-[50ms] ease-linear"
              style={{ 
                width: idx === currentIndex ? `${progress}%` : idx < currentIndex ? '100%' : '0%' 
              }}
            ></div>
          </div>
        ))}
      </div>

      {/* Header / Controles */}
      <div className="absolute top-6 left-0 w-full px-8 flex items-center justify-between z-10">
        <div className="flex flex-col">
          <span className="text-white/60 text-[10px] font-black uppercase tracking-[0.3em] mb-1">{title}</span>
          <h2 className="text-white text-2xl font-black tracking-tight drop-shadow-lg">
            {currentSlide.locationName}
          </h2>
        </div>
        <button 
          onClick={onClose}
          className="w-12 h-12 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center text-white transition-all hover:rotate-90"
        >
          <i className="fa-solid fa-xmark text-xl"></i>
        </button>
      </div>

      {/* Visor de Imágenes (Fotos originales, sin alteración) */}
      <div className="relative w-full h-full flex items-center justify-center p-4">
        {slides.map((slide, idx) => (
          <img
            key={idx}
            src={slide.image}
            alt={`Foto ${idx}`}
            className={`absolute max-w-full max-h-[80vh] object-contain transition-all duration-1000 shadow-[0_0_100px_rgba(0,0,0,0.5)] rounded-lg ${
              idx === currentIndex ? 'opacity-100 scale-100 translate-z-0' : 'opacity-0 scale-105 pointer-events-none'
            }`}
          />
        ))}
      </div>

      {/* Controles Inferiores e Información */}
