import React, { useState, useEffect, useRef } from 'react';
import { generateNarration, playAudioBuffer } from '../services/audioService';

export interface Slide {
  image: string;
  locationName: string;
  description: string;
  facts: string[];
}

interface PresentationModeProps {
  slides: Slide[];
  onClose: () => void;
  title: string;
}

const PresentationMode: React.FC<PresentationModeProps> = ({ slides, onClose, title }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);
  const [progress, setProgress] = useState(0);
  const [isNarrating, setIsNarrating] = useState(false);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const SLIDE_DURATION = 5000; // 5 segundos por foto
  const currentSlide = slides[currentIndex];

  // Lógica de transición automática y barra de progreso
  useEffect(() => {
    let interval: number;
    let progressInterval: number;

    if (isPlaying) {
      const startTime = Date.now();

      interval = window.setInterval(() => {
        setCurrentIndex((prev) => (prev + 1) % slides.length);
        setProgress(0);
      }, SLIDE_DURATION);

      progressInterval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        const newProgress = Math.min((elapsed / SLIDE_DURATION) * 100, 100);
        setProgress(newProgress);
      }, 50);
    }

    return () => {
      clearInterval(interval);
      clearInterval(progressInterval);
    };
  }, [isPlaying, currentIndex, slides.length]);

  const handleToggleNarration = async () => {
    if (isNarrating) {
      audioSourceRef.current?.stop();
      setIsNarrating(false);
      return;
    }

    try {
      setIsPlaying(false); // Pausamos el auto-play mientras narra
      setIsNarrating(true);
      const text = `${currentSlide.locationName}. ${currentSlide.description}.`;
      const buffer = await generateNarration(text);
      audioSourceRef.current = playAudioBuffer(buffer);
      audioSourceRef.current.onended = () => {
        setIsNarrating(false);
        setIsPlaying(true);
      };
    } catch (err) {
      console.error(err);
      setIsNarrating(false);
      setIsPlaying(true);
    }
  };

  useEffect(() => {
    return () => audioSourceRef.current?.stop();
  }, []);

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col md:flex-row animate-in fade-in duration-500 overflow-hidden">
      {/* Botón de Cerrar (Flotante) */}
      <button 
        onClick={onClose}
        className="absolute top-6 right-6 w-12 h-12 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center text-white z-50 transition-all hover:rotate-90 border border-white/10"
      >
        <i className="fa-solid fa-xmark text-xl"></i>
      </button>

      {/* Área Principal: Visor de Imágenes */}
      <div className="flex-1 relative flex flex-col items-center justify-center p-4 md:p-12 overflow-hidden bg-zinc-950">
        {/* Barras de progreso superiores */}
        <div className="absolute top-0 left-0 w-full p-4 flex gap-1 z-20">
          {slides.map((_, idx) => (
            <div key={idx} className="h-1 flex-1 bg-white/10 rounded-full overflow-hidden">
              <div 
                className="h-full bg-white transition-all duration-[50ms] ease-linear shadow-[0_0_8px_rgba(255,255,255,0.5)]"
                style={{ 
                  width: idx === currentIndex ? `${progress}%` : idx < currentIndex ? '100%' : '0%' 
                }}
              ></div>
            </div>
          ))}
        </div>

        {/* Imágenes (Fidelidad absoluta) */}
        <div className="relative w-full h-full flex items-center justify-center">
          {slides.map((slide, idx) => (
            <img
              key={idx}
              src={slide.image}
              alt={`Foto ${idx}`}
              className={`absolute max-w-full max-h-full object-contain transition-all duration-1000 shadow-[0_0_80px_rgba(0,0,0,0.8)] rounded-lg ${
                idx === currentIndex ? 'opacity-100 scale-100' : 'opacity-0 scale-105 pointer-events-none'
              }`}
            />
          ))}
        </div>

        {/* Controles de Reproducción (Centro Abajo) */}
        <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-8 z-30 bg-black/40 backdrop-blur-xl px-8 py-4 rounded-full border border-white/5">
          <button 
            onClick={() => {
              setCurrentIndex((prev) => (prev - 1 + slides.length) % slides.length);
              setProgress(0);
            }}
            className="w-10 h-10 text-white/40 hover:text-white transition-colors"
          >
            <i className="fa-solid fa-backward-step text-xl"></i>
          </button>

          <button 
            onClick={() => setIsPlaying(!isPlaying)}
            className="w-14 h-14 bg-white text-black rounded-full flex items-center justify-center shadow-xl hover:scale-110 active:scale-95 transition-all"
          >
            <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'} text-xl`}></i>
          </button>

          <button 
            onClick={() => {
              setCurrentIndex((prev) => (prev + 1) % slides.length);
              setProgress(0);
            }}
            className="w-10 h-10 text-white/40 hover:text-white transition-colors"
          >
            <i className="fa-solid fa-forward-step text-xl"></i>
          </button>
        </div>
      </div>

      {/* Panel Lateral: Información (Costado Derecho) */}
      <div className="w-full md:w-[420px] h-[45%] md:h-full bg-slate-900/40 backdrop-blur-3xl border-l border-white/5 p-8 md:p-12 flex flex-col justify-center z-10 overflow-y-auto">
        <div className="animate-in slide-in-from-right-12 duration-1000">
          <div className="mb-10">
            <span className="text-indigo-400 text-[10px] font-black uppercase tracking-[0.4em] mb-4 block opacity-70">
              {title}
            </span>
            <h2 className="text-white text-4xl md:text-5xl font-black tracking-tight leading-tight">
              {currentSlide.locationName}
            </h2>
          </div>

          <div className="space-y-10">
            <div className="relative">
              <i className="fa-solid fa-quote-left text-white/10 text-6xl absolute -top-6 -left-4"></i>
              <p className="text-white/90 text-lg md:text-xl leading-relaxed italic relative z-10 pl-2">
                {currentSlide.description}
              </p>
            </div>

            <div className="space-y-6 pt-6 border-t border-white/5">
              <h4 className="text-[10px] font-black text-white/30 uppercase tracking-[0.2em]">Curiosidades del lugar</h4>
              <div className="grid grid-cols-1 gap-3">
                {currentSlide.facts.map((fact, fidx) => (
                  <div key={fidx} className="bg-white/5 border border-white/10 p-4 rounded-[1.5rem] flex items-start gap-4 transition-all hover:bg-white/10">
                    <div className="w-6 h-6 bg-indigo-500/20 text-indigo-400 rounded-lg flex items-center justify-center shrink-0 text-[10px] font-bold">
                      {fidx + 1}
                    </div>
                    <p className="text-sm text-white/70 leading-snug">{fact}</p>
                  </div>
                ))}
              </div>
            </div>

            <button 
              onClick={handleToggleNarration}
              className={`w-full flex items-center justify-center gap-4 px-8 py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] transition-all ${
                isNarrating 
                  ? 'bg-indigo-600 text-white shadow-[0_0_30px_rgba(79,70,229,0.3)] animate-pulse' 
                  : 'bg-white/5 text-white hover:bg-white/10 border border-white/10'
              }`}
            >
              <i className={`fa-solid ${isNarrating ? 'fa-stop-circle' : 'fa-podcast'} text-lg`}></i>
              {isNarrating ? 'Detener Narración' : 'Escuchar Guía de Voz'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

