import { GoogleGenAI, Modality } from "@google/genai";

export const generateAtmosphere = async (locationName: string, country: string): Promise<AudioBuffer> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Prompt especializado para generar una atmósfera musical en lugar de habla
  const prompt = `
    Realiza una interpretación musical ambiental (sin palabras, solo sonidos) que represente la cultura de ${country} y el lugar ${locationName}. 
    Utiliza sonidos que imiten instrumentos tradicionales típicos de la región (por ejemplo: flautas, cuerdas, percusión rítmica). 
    La pieza debe ser evocadora, relajante y puramente instrumental/vocal rítmica. 
    Duración: 60 segundos de atmósfera musical continua.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: prompt }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Puck' }, // Usamos Puck por su rango dinámico para sonidos no verbales
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("No se pudo generar la atmósfera musical.");

  const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  const audioBuffer = await decodeAudioData(decode(base64Audio), audioContext, 24000, 1);

  return audioBuffer;
};

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const playAudioBuffer = (buffer: AudioBuffer, loop: boolean = true) => {
  const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
  const source = ctx.createBufferSource();
  source.buffer = buffer;
  source.loop = loop;
  source.connect(ctx.destination);
  source.start();
  return { source, ctx };
};

import React, { useState, useEffect, useRef } from 'react';
import { generateAtmosphere, playAudioBuffer } from '../services/audioService';

