import React, { useState, useEffect, useRef } from 'react';
import { generateAtmosphere, playAudioBuffer } from '../services/audioService';

export interface Slide {
  image: string;
  locationName: string;
  description: string;
  facts: string[];
  country?: string;
}

interface PresentationModeProps {
  slides: Slide[];
  onClose: () => void;
  title: string;
}

const PresentationMode: React.FC<PresentationModeProps> = ({ slides, onClose, title }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);
  const [progress, setProgress] = useState(0);
  const [isMusicLoading, setIsMusicLoading] = useState(true);

  const audioRef = useRef<{ source: AudioBufferSourceNode, ctx: AudioContext } | null>(null);
  const SLIDE_DURATION = 5000;
  const currentSlide = slides[currentIndex];

  // Iniciar Música Ambiental
  useEffect(() => {
    const initMusic = async () => {
      try {
        setIsMusicLoading(true);
        // Generamos música basada en el primer destino o el título
        const firstCountry = slides[0].country || "el mundo";
        const buffer = await generateAtmosphere(slides[0].locationName, firstCountry);
        audioRef.current = playAudioBuffer(buffer, true);
        setIsMusicLoading(false);
      } catch (err) {
        console.error("No se pudo cargar la música:", err);
        setIsMusicLoading(false);
      }
    };

    initMusic();
    return () => {
      audioRef.current?.source.stop();
      audioRef.current?.ctx.close();
    };
  }, []);

  // Transición automática
  useEffect(() => {
    let interval: number;
    let progressInterval: number;

    if (isPlaying) {
      const startTime = Date.now();

      interval = window.setInterval(() => {
        setCurrentIndex((prev) => (prev + 1) % slides.length);
        setProgress(0);
      }, SLIDE_DURATION);

      progressInterval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        const newProgress = Math.min((elapsed / SLIDE_DURATION) * 100, 100);
        setProgress(newProgress);
      }, 50);
    }

    return () => {
      clearInterval(interval);
      clearInterval(progressInterval);
    };
  }, [isPlaying, currentIndex, slides.length]);

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col md:flex-row animate-in fade-in duration-700 overflow-hidden">
      {/* Botón de Cerrar */}
      <button 
        onClick={onClose}
        className="absolute top-6 right-6 w-12 h-12 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center text-white z-50 transition-all border border-white/10"
      >
        <i className="fa-solid fa-xmark text-xl"></i>
      </button>

      {/* ÁREA DE IMAGEN (Izquierda/Centro) */}
      <div className="flex-1 relative flex items-center justify-center p-4 md:p-12 bg-zinc-950 overflow-hidden">
        {/* Barra de progreso global (superior) */}
        <div className="absolute top-0 left-0 w-full p-4 flex gap-1.5 z-20">
          {slides.map((_, idx) => (
            <div key={idx} className="h-1 flex-1 bg-white/10 rounded-full overflow-hidden">
              <div 
                className="h-full bg-white transition-all duration-[50ms] ease-linear shadow-[0_0_10px_white]"
                style={{ 
                  width: idx === currentIndex ? `${progress}%` : idx < currentIndex ? '100%' : '0%' 
                }}
              ></div>
            </div>
          ))}
        </div>

        {/* Galería de Fotos (Fidelidad total) */}
        <div className="relative w-full h-full flex items-center justify-center">
          {slides.map((slide, idx) => (
            <img
              key={idx}
              src={slide.image}
              alt={slide.locationName}
              className={`absolute max-w-full max-h-full object-contain transition-all duration-1000 rounded-lg shadow-[0_0_100px_rgba(0,0,0,1)] ${
                idx === currentIndex ? 'opacity-100 scale-100' : 'opacity-0 scale-105 pointer-events-none'
              }`}
            />
          ))}
        </div>

        {/* Indicador de Música */}
        <div className="absolute top-10 left-10 flex items-center gap-3 bg-black/40 backdrop-blur-md px-4 py-2 rounded-full border border-white/5 z-30">
          <div className="flex gap-1 h-3 items-end">
            <div className={`w-1 bg-indigo-400 ${isPlaying ? 'animate-[bounce_1s_infinite_delay-100]' : 'h-1'}`}></div>
            <div className={`w-1 bg-indigo-400 ${isPlaying ? 'animate-[bounce_1s_infinite_delay-300]' : 'h-2'}`}></div>
            <div className={`w-1 bg-indigo-400 ${isPlaying ? 'animate-[bounce_1s_infinite_delay-500]' : 'h-1.5'}`}></div>
          </div>
          <span className="text-[10px] text-white/60 font-black uppercase tracking-widest">
            {isMusicLoading ? 'Cargando Atmósfera...' : 'Música Tradicional'}
          </span>
        </div>

        {/* Controles de Reproducción */}
        <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-10 z-30 bg-black/40 backdrop-blur-2xl px-10 py-5 rounded-full border border-white/10">
          <button 
            onClick={() => { setCurrentIndex((prev) => (prev - 1 + slides.length) % slides.length); setProgress(0); }}
            className="text-white/40 hover:text-white transition-colors"
          >
            <i className="fa-solid fa-backward-step text-xl"></i>
          </button>

          <button 
            onClick={() => setIsPlaying(!isPlaying)}
            className="w-16 h-16 bg-white text-black rounded-full flex items-center justify-center shadow-2xl hover:scale-110 active:scale-95 transition-all"
          >
            <i className={`fa-solid ${isPlaying ? 'fa-pause' : 'fa-play'} text-2xl`}></i>
          </button>

          <button 
            onClick={() => { setCurrentIndex((prev) => (prev + 1) % slides.length); setProgress(0); }}
            className="text-white/40 hover:text-white transition-colors"
          >
            <i className="fa-solid fa-forward-step text-xl"></i>
          </button>
        </div>
      </div>

      {/* PANEL DE INFORMACIÓN (Derecha) */}
      <div className="w-full md:w-[420px] h-[40%] md:h-full bg-slate-900 border-l border-white/5 flex flex-col z-40 shadow-2xl">
        <div className="flex-1 overflow-y-auto p-8 md:p-12 flex flex-col justify-center">
          <div className="animate-in slide-in-from-right-10 duration-1000">
            <span className="text-indigo-400 text-[10px] font-black uppercase tracking-[0.4em] mb-4 block">
              {title}
            </span>
            <h2 className="text-white text-4xl md:text-5xl font-black tracking-tight leading-tight mb-8">
              {currentSlide.locationName}
            </h2>

            <div className="relative mb-6">
              <i className="fa-solid fa-quote-left text-indigo-500/20 text-6xl absolute -top-8 -left-6"></i>
              <p className="text-white/80 text-lg md:text-xl leading-relaxed italic relative z-10 pl-2">
                {currentSlide.description}
              </p>
            </div>

            {/* Se han eliminado los secretos del lugar para una mejor visualización del texto descriptivo */}
          </div>
        </div>

        {/* Footer del panel */}
        <div className="p-8 border-t border-white/5 bg-black/20">
          <div className="flex items-center justify-between text-[10px] text-white/30 font-bold uppercase tracking-widest">
            <span>{currentSlide.country}</span>
            <span>{currentIndex + 1} / {slides.length}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

