  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  /**
   * El modelo TTS (Text-to-Speech) genera audio a partir de texto.
   * Para simular una "atmósfera", le pedimos que realice sonidos melódicos
   * y rítmicos usando onomatopeyas y tarareos (humming).
   */
  const prompt = `
    Crea una atmósfera sonora rítmica y relajante para el lugar: ${locationName}, ${country}.
    Instrucción: No hables, no digas palabras reales. 
    Interpreta únicamente sonidos vocales rítmicos y melódicos como "Hummmm, ahhhh, mmmm-hmm" 
    que sigan un patrón musical tradicional de la región.
    Duración: 20-30 segundos de armonía vocal pura.
