// URL de una pista relajante de dominio público (Satie - Gymnopédie No. 1)
const RELAXING_TRACK_URL = 'https://www.chosic.com/wp-content/uploads/2021/04/Gymnopedie-No-1.mp3';

/**
 * Carga una atmósfera sonora relajante desde un recurso estático.
 * Se mantiene la firma para no romper la compatibilidad con los componentes existentes.
 */
export const generateAtmosphere = async (locationName?: string, country?: string): Promise<AudioBuffer> => {
  try {
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();

    // Descargamos el archivo de audio
    const response = await fetch(RELAXING_TRACK_URL);
    if (!response.ok) throw new Error("No se pudo descargar la pista de audio.");

    const arrayBuffer = await response.arrayBuffer();

    // Decodificamos el formato (MP3/WAV) usando el método nativo del navegador
    return await audioContext.decodeAudioData(arrayBuffer);
  } catch (err) {
    console.error("Error cargando la música ambiental:", err);
    throw err;
  }
};

/**
 * Reproduce un AudioBuffer y permite control de bucle.
 */
export const playAudioBuffer = (buffer: AudioBuffer, loop: boolean = true) => {
  const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
  const source = ctx.createBufferSource();
  source.buffer = buffer;
  source.loop = loop;

  // Creamos un nodo de ganancia para un fundido de entrada suave
  const gainNode = ctx.createGain();
  gainNode.gain.setValueAtTime(0, ctx.currentTime);
  gainNode.gain.linearRampToValueAtTime(0.5, ctx.currentTime + 2); // Volumen al 50% en 2 segundos

  source.connect(gainNode);
  gainNode.connect(ctx.destination);

  source.start();
  return { source, ctx };
};

