const AMBIENT_TRACK_URL = 'https://upload.wikimedia.org/wikipedia/commons/5/53/Erik_Satie_-_Gymnop%C3%A9die_No._1.mp3';

export class GeoAudioPlayer {
  private audio: HTMLAudioElement | null = null;
  private isMuted: boolean = false;

  constructor() {
    this.audio = new Audio(AMBIENT_TRACK_URL);
    this.audio.loop = true;
    this.audio.volume = 0.4;
    // Aseguramos que el navegador no bloquee la carga por CORS si es posible
    this.audio.crossOrigin = "anonymous";
  }

  play() {
    if (this.audio) {
      this.audio.play().catch(err => {
        console.warn("Auto-play bloqueado o error de carga de audio:", err);
      });
    }
  }

  pause() {
    this.audio?.pause();
  }

  toggleMute() {
    if (this.audio) {
      this.isMuted = !this.isMuted;
      this.audio.muted = this.isMuted;
      return this.isMuted;
    }
    return false;
  }

  stop() {
    if (this.audio) {
      this.audio.pause();
      this.audio.currentTime = 0;
    }
  }
}

export const createAudioPlayer = () => new GeoAudioPlayer();

