const AMBIENT_TRACK_URL = 'https://upload.wikimedia.org/wikipedia/commons/5/53/Erik_Satie_-_Gymnop%C3%A9die_No._1.mp3';

export class GeoAudioPlayer {
  private audio: HTMLAudioElement;
  private isMuted: boolean = false;

  constructor() {
    this.audio = new Audio();
    this.audio.src = AMBIENT_TRACK_URL;
    this.audio.loop = true;
    this.audio.volume = 0.5;
    this.audio.preload = 'auto';
  }

  async play() {
    try {
      if (this.audio.paused) {
        await this.audio.play();
        console.log("Audio iniciado correctamente");
      }
    } catch (err) {
      console.warn("Autoplay bloqueado temporalmente por el navegador. Esperando interacción del usuario.");
      throw err; // Re-lanzar para que el componente pueda manejarlo
    }
  }

  pause() {
    this.audio.pause();
  }

  toggleMute() {
    this.isMuted = !this.isMuted;
    this.audio.muted = this.isMuted;
    return this.isMuted;
  }

  stop() {
    this.audio.pause();
    this.audio.currentTime = 0;
  }

  setVolume(val: number) {
    this.audio.volume = Math.max(0, Math.min(1, val));
  }
}

export const createAudioPlayer = () => new GeoAudioPlayer();

import React, { useState, useEffect, useRef } from 'react';
import { createAudioPlayer } from '../services/audioService';

export interface Slide {
  image: string;
  locationName: string;
  description: string;
  facts: string[];
  country?: string;
}

interface PresentationModeProps {
  slides: Slide[];
  onClose: () => void;
  title: string;
}

const PresentationMode: React.FC<PresentationModeProps> = ({ slides, onClose, title }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);
  const [isMuted, setIsMuted] = useState(false);
  const [progress, setProgress] = useState(0);
  const audioPlayerRef = useRef<any>(null);
  const hasInteractedRef = useRef(false);

  const SLIDE_DURATION = 6000;
  const currentSlide = slides[currentIndex];

  // Inicializar Audio y manejar política de Autoplay
  useEffect(() => {
    audioPlayerRef.current = createAudioPlayer();

    const startAudio = async () => {
      try {
        await audioPlayerRef.current.play();
      } catch (e) {
        // El audio está bloqueado, se activará en el primer clic
        console.log("Esperando clic para activar sonido...");
      }
    };

    startAudio();

    // Listener de rescate: si el autoplay falla, cualquier clic en la pantalla activa el audio
    const handleFirstInteraction = () => {
      if (!hasInteractedRef.current && audioPlayerRef.current) {
        audioPlayerRef.current.play().catch(() => {});
        hasInteractedRef.current = true;
      }
    };

    window.addEventListener('click', handleFirstInteraction);

    return () => {
      audioPlayerRef.current?.stop();
      window.removeEventListener('click', handleFirstInteraction);
    };
  }, []);

  // Transición automática de diapositivas
  useEffect(() => {
    let interval: number;
    let progressInterval: number;

    if (isPlaying) {
      const startTime = Date.now();

      interval = window.setInterval(() => {
        setCurrentIndex((prev) => (prev + 1) % slides.length);
        setProgress(0);
      }, SLIDE_DURATION);

      progressInterval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        const newProgress = Math.min((elapsed / SLIDE_DURATION) * 100, 100);
        setProgress(newProgress);
      }, 50);
    }

    return () => {
      clearInterval(interval);
      clearInterval(progressInterval);
    };
  }, [isPlaying, currentIndex, slides.length]);

  const handleToggleMute = (e: React.MouseEvent) => {
    e.stopPropagation(); // Evitar que el clic del mute dispare otros eventos
    if (audioPlayerRef.current) {
      const muted = audioPlayerRef.current.toggleMute();
      setIsMuted(muted);
    }
  };

  const togglePlay = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsPlaying(!isPlaying);
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black flex flex-col md:flex-row animate-in fade-in duration-700 overflow-hidden">
      {/* Botón de Cerrar */}
      <button 
        onClick={onClose}
        className="absolute top-6 right-6 w-12 h-12 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center text-white z-50 transition-all border border-white/10"
      >
        <i className="fa-solid fa-xmark text-xl"></i>
      </button>

      {/* Indicador de Audio / Mute */}
      <button 
        onClick={handleToggleMute}
        className="absolute top-6 left-6 h-12 px-4 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full flex items-center gap-3 text-white z-50 transition-all border border-white/10 group"
      >
        <div className="flex gap-1 h-3 items-end">
          <div className={`w-0.5 bg-white transition-all ${!isMuted && isPlaying ? 'animate-[bounce_1s_infinite_delay-100]' : 'h-0.5'}`}></div>
          <div className={`w-0.5 bg-white transition-all ${!isMuted && isPlaying ? 'animate-[bounce_1s_infinite_delay-300]' : 'h-2'}`}></div>
          <div className={`w-0.5 bg-white transition-all ${!isMuted && isPlaying ? 'animate-[bounce_1s_infinite_delay-500]' : 'h-1.5'}`}></div>
        </div>
        <span className="text-[10px] font-bold uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity hidden sm:inline">
          {isMuted ? 'Mudo' : 'Sonido'}
        </span>
        <i className={`fa-solid ${isMuted ? 'fa-volume-xmark' : 'fa-volume-high'} text-xs ml-1`}></i>
      </button>

      {/* ÁREA DE IMAGEN */}
      <div className="flex-1 relative flex items-center justify-center p-4 md:p-12 bg-zinc-950 overflow-hidden">
        {/* Barras de progreso superiores */}
        <div className="absolute top-0 left-0 w-full p-4 flex gap-2 z-20">
          {slides.map((_, idx) => (
            <div key={idx} className="h-1 flex-1 bg-white/10 rounded-full overflow-hidden">
              <div 
                className="h-full bg-white transition-all duration-[50ms] ease-linear shadow-[0_0_8px_white]"
                style={{ 
                  width: idx === currentIndex ? `${progress}%` : idx < currentIndex ? '100%' : '0%' 
                }}
              ></div>
            </div>
          ))}
        </div>

        {/* Galería de Fotos */}
        <div className="relative w-full h-full flex items-center justify-center">
          {slides.map((slide, idx) => (
            <img
              key={idx}
              src={slide.image}
              alt={slide.locationName}
              className={`absolute max-w-full max-h-full object-contain transition-all duration-1000 rounded-lg shadow-[0_0_100px_rgba(0,0,0,0.5)] ${
                idx === currentIndex ? 'opacity-100 scale-100' : 'opacity-0 scale-110 pointer-events-none'
              }`}
            />
          ))}
        </div>

        {/* Controles de Reproducción Inferiores */}
        <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-8 z-30 bg-black/40 backdrop-blur-2xl px-8 py-4 rounded-full border border-white/10">
          <button 
