// Usamos una pista de Pixabay que suele tener mejores cabeceras de CDN y mayor compatibilidad
const AMBIENT_TRACK_URL = 'https://cdn.pixabay.com/audio/2022/08/02/audio_8845892534.mp3';

export class GeoAudioPlayer {
  private audio: HTMLAudioElement;
  private isMuted: boolean = false;

  constructor() {
    this.audio = new Audio();
    // Importante: Algunos servidores requieren anonymous para evitar problemas de CORS en elementos media
    this.audio.crossOrigin = "anonymous";
    this.audio.src = AMBIENT_TRACK_URL;
    this.audio.loop = true;
    this.audio.volume = 0.4;
    this.audio.preload = 'auto';

    this.audio.onerror = () => {
      console.error("Error en el elemento de audio:", this.audio.error);
    };
  }

  async play() {
    try {
      // Si el src falló por alguna razón, intentamos recargar antes de reproducir
      if (this.audio.error) {
        console.warn("Reintentando carga de audio tras error previo...");
        this.audio.load();
      }

      if (this.audio.paused) {
        const playPromise = this.audio.play();
        if (playPromise !== undefined) {
          await playPromise;
          console.log("Audio iniciado correctamente:", AMBIENT_TRACK_URL);
        }
      }
    } catch (err) {
      console.warn("No se pudo iniciar la reproducción automática:", err);
      throw err;
    }
  }

  pause() {
    this.audio.pause();
  }

  toggleMute() {
    this.isMuted = !this.isMuted;
    this.audio.muted = this.isMuted;
    return this.isMuted;
  }

  stop() {
    this.audio.pause();
    this.audio.currentTime = 0;
  }

  setVolume(val: number) {
    this.audio.volume = Math.max(0, Math.min(1, val));
  }
}

export const createAudioPlayer = () => new GeoAudioPlayer();

